WITH x8 AS (SELECT 1 AS x12, 'G' AS x13, 40 AS x14 UNION SELECT 2, 'G', 60 UNION SELECT 3, 'S', 60 UNION SELECT 'abcdefghijkl') SELECT x7.STDDEV_SAMP(RPAD(1.0, 2048, 1)), x7.STDDEV_SAMP(RPAD(1.0, 2048, 1)), ST_INTERSECTS(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION()'), ST_GEOMFROMTEXT('POINT(0 0)')) AS x4, x7.STDDEV_SAMP(RPAD(1.0, 2048, 1)) FROM v61083 AS x7 WHERE x7.STDDEV_SAMP(RPAD(1.0, 2048, 1)) > 8 OR ((x7.STDDEV_SAMP(RPAD(1.0, 2048, 1)) BETWEEN 9 AND 13) AND x7.STDDEV_SAMP(RPAD(1.0, 2048, 1)) = 90)